insert into todo.donde_pages (page_id, sort, title_es, title_en, visual_layer) values ('sb_apt_01', 1, 'El apartamento desplegable', 'The Fold-Out Apartment', 'pop_up_apartment') on conflict (page_id) do update set sort = excluded.sort, title_es = excluded.title_es, title_en = excluded.title_en, visual_layer = excluded.visual_layer;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('apt_toys', 'sb_apt_01', 1, 'drag', 'Pon los juguetes dentro de la caja de cartón.', 'Put the toys inside the cardboard box.', 'paper_toys', 'zone_inside_box', 'You placed it fuera de la caja (outside the box). Drag it inside the lines.', '¡Muy bien! Los juguetes están dentro de la caja.', '{"zone_on_box":"That''s encima de la caja (on top of the box). Dentro de = inside."}'::jsonb, null, array['dentro de', 'fuera de', 'encima de']::text[], 'A1') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('apt_cat', 'sb_apt_01', 2, 'flap', 'El gato está debajo del sofá.', 'The cat is under the sofa. Lift the right cover.', null, 'flap_under_sofa', 'Look for the cover debajo del sofá (under the sofa).', '¡Ahí está! Debajo del sofá. (de + el = del)', '{"flap_on_sofa":"That flap is encima del sofá (on top of the sofa). Debajo de = under.","flap_behind_curtain":"That''s detrás de la cortina (behind the curtain). Look debajo del sofá."}'::jsonb, null, array['debajo de', 'encima de', 'detrás de', 'del']::text[], 'A1') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('apt_cat_label', 'sb_apt_01', 3, 'build', '¿Hay o está? Describe al gato.', 'Hay or está? Label the cat with the Dymo stickers.', null, 'label_under_sofa', 'Almost. Say "El gato está…" (the cat we found) or "Hay un gato…" (there is a cat).', 'Both work: El gato está… (a specific cat) · Hay un gato… (a cat exists there).', '{}'::jsonb, '{"template":"{0} {1} debajo del sofá.","tokens":["hay","está","el gato","un gato"],"answers":[["el gato","está"],["hay","un gato"]]}'::jsonb, array['hay vs estar']::text[], 'A1') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('apt_clothes', 'sb_apt_01', 4, 'pick', 'La ropa de la niña está en el piso de arriba.', 'The girl''s clothes are upstairs. Find them.', null, 'pick_clothes_upstairs', 'Look arriba (upstairs). Switch to the top floor.', '¡Eso es! La ropa está arriba, en el piso de arriba.', '{"pick_laundry_downstairs":"That laundry is abajo (downstairs). Arriba = upstairs. Go up a floor!"}'::jsonb, null, array['arriba', 'abajo']::text[], 'A1') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('apt_backpack', 'sb_apt_01', 5, 'drag', 'Pon la mochila encima de la cama.', 'Put the backpack on top of the bed.', 'paper_backpack', 'zone_on_bed', 'Encima de la cama = on top of the bed. Drop it on the bed.', '¡Lista! La mochila está encima de la cama. (In Latin America you''ll also hear arriba de la cama.)', '{"zone_under_bed":"That''s debajo de la cama (under the bed). Encima de = on top of."}'::jsonb, null, array['encima de', 'debajo de', 'arriba de']::text[], 'A1') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
