insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('plaza_fountain', 'sb_plaza_02', 1, 'drag', 'La fuente está en medio de la plaza.', 'The fountain is in the middle of the square.', 'paper_fountain', 'zone_plaza_center', 'En medio de = in the middle. Put it right in the center of the square.', '¡Perfecto! En medio de la plaza (también: en el centro de la plaza).', '{"zone_plaza_corner":"That''s en la esquina de la plaza (in the corner). En medio de = in the middle."}'::jsonb, null, array['en medio de', 'en el centro de']::text[], 'A1') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('plaza_chairs', 'sb_plaza_02', 2, 'drag', 'Pon las sillas de papel alrededor de la mesa.', 'Put the paper chairs around the table.', 'paper_chairs', 'zone_around_table', 'Alrededor de = around. Put each chair on one side of the table.', '¡Qué bonito! Las sillas están alrededor de la mesa.', '{}'::jsonb, null, array['alrededor de']::text[], 'A2') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('plaza_chairs_label', 'sb_plaza_02', 3, 'build', '¿Hay o están? Describe la terraza.', 'Hay or están? Label the terrace.', null, 'label_table', 'Say "Hay cuatro sillas…" (there are four chairs) or "Las sillas están…" (the chairs are).', 'Hay + a number · están + the specific chairs.', '{}'::jsonb, '{"template":"{0} {1} alrededor de la mesa.","tokens":["hay","está","están","las sillas","cuatro sillas"],"answers":[["hay","cuatro sillas"],["las sillas","están"]]}'::jsonb, array['hay vs estar', 'agreement']::text[], 'A2') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('plaza_kiosk', 'sb_plaza_02', 4, 'drag', 'El quiosco está entre el banco y la panadería.', 'The kiosk is between the bank and the bakery.', 'paper_kiosk', 'zone_between_bank_bakery', 'Entre A y B = between A and B. Find the gap between the two buildings.', '¡Exacto! El quiosco está entre el banco y la panadería.', '{"zone_next_to_bakery":"That''s al lado de la panadería (next to it), but not entre. Entre A y B = between A and B.","zone_behind_bank":"That''s detrás del banco (behind the bank). Look for the gap between the two."}'::jsonb, null, array['entre', 'al lado de', 'detrás de']::text[], 'A1') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('plaza_bike', 'sb_plaza_02', 5, 'drag', 'Pon la bicicleta junto a la fuente.', 'Put the bicycle next to the fountain.', 'paper_bike', 'zone_next_to_fountain', 'Junto a = al lado de = right next to. Put it beside the fountain.', '¡Bien! Junto a la fuente = al lado de la fuente.', '{"zone_far_from_fountain":"That''s lejos de la fuente (far from it). Junto a = right next to."}'::jsonb, null, array['junto a', 'al lado de']::text[], 'A2') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
