insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('map_pharmacy', 'sb_map_03', 1, 'pin', 'La farmacia está enfrente del parque.', 'The pharmacy is across from the park. Pin it.', null, 'pin_across_park', 'Enfrente de = across the street, facing it.', '¡Sí! Enfrente del parque = across the street. (También: frente al parque.)', '{"pin_next_to_park":"That building is al lado del parque (same side of the street). Enfrente de = across the street, facing it.","pin_behind_park":"That''s detrás del parque (behind it). Look across the street."}'::jsonb, null, array['enfrente de', 'frente a', 'al lado de']::text[], 'A2') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('map_pharmacy_label', 'sb_map_03', 2, 'build', 'de + el = ? Completa la etiqueta.', 'Complete the label: de + el = ?', null, 'label_pharmacy', 'Parque is masculine (el parque), so de + el parque → del parque.', 'de + el = del · a + el = al. Always contract.', '{}'::jsonb, '{"template":"La farmacia está enfrente {0} parque.","tokens":["de el","del","de la"],"answers":[["del"]]}'::jsonb, array['del', 'contractions']::text[], 'A1') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('map_taxi', 'sb_map_03', 3, 'pick', 'El taxi está delante de la casa.', 'The taxi is in front of the house. Find it.', null, 'pick_taxi_ahead', 'Delante de = in front of: on the side the front door faces.', '¡Correcto! El taxi está delante de la casa.', '{"pick_taxi_behind":"That taxi is detrás de la casa (behind the house). Delante de = in front of."}'::jsonb, null, array['delante de', 'detrás de']::text[], 'A2') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
insert into todo.donde_tasks (id, page_id, sort, mechanic, prompt_text, prompt_en, draggable_id, target_zone, error_note, success_note, zone_notes, build, tags, level) values ('map_home', 'sb_map_03', 4, 'pin', 'Vivo cerca del centro, pero lejos de la autopista.', 'I live near the center, but far from the highway. Pin my block.', null, 'pin_block_b', 'Find the block that is cerca del centro and lejos de la autopista.', '¡Esa es mi casa! Cerca del centro, lejos de la autopista.', '{"pin_block_a":"That block is cerca del centro, but also cerca de la autopista (near the highway).","pin_block_c":"That block is lejos del centro (far from the center)."}'::jsonb, null, array['cerca de', 'lejos de']::text[], 'A2') on conflict (id) do update set page_id = excluded.page_id, sort = excluded.sort, mechanic = excluded.mechanic, prompt_text = excluded.prompt_text, prompt_en = excluded.prompt_en, draggable_id = excluded.draggable_id, target_zone = excluded.target_zone, error_note = excluded.error_note, success_note = excluded.success_note, zone_notes = excluded.zone_notes, build = excluded.build, tags = excluded.tags, level = excluded.level;
